{
  "name": "opencode-session-process-timeline",
  "version": "0.1.4",
  "description": "Show the shell/process timeline of an OpenCode session in the TUI and Desktop GUI.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": ["src", "dist"],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "process",
    "timeline",
    "session"
  ],
  "license": "MIT",
  "author": "Wenjie Chen <wenjie.chen@houmo.ai>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vinojeff/opencode-session-process-timeline.git"
  },
  "homepage": "https://github.com/vinojeff/opencode-session-process-timeline#readme",
  "bugs": {
    "url": "https://github.com/vinojeff/opencode-session-process-timeline/issues"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.5"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "vite": "^7.1.12",
    "vite-plugin-solid": "^2.11.10"
  }
}
